INSERT OR IGNORE INTO sides (topic_id, device, side, updated_at) SELECT (SELECT id FROM topics WHERE code = 'DB0001'), 'mock-00001', 'pro', 1794657600000 WHERE (SELECT id FROM topics WHERE code = 'DB0001') IS NOT NULL;
