INSERT OR IGNORE INTO sides (topic_id, device, side, updated_at) SELECT (SELECT id FROM topics WHERE code = 'DB0006'), 'mock-00262', 'pro', 1795780800000 WHERE (SELECT id FROM topics WHERE code = 'DB0006') IS NOT NULL;
INSERT INTO monthly (topic_id, month, n) SELECT (SELECT id FROM topics WHERE code = 'DB0006'), '2026-11', 96 WHERE (SELECT id FROM topics WHERE code = 'DB0006') IS NOT NULL ON CONFLICT (topic_id, month) DO UPDATE SET n = n + excluded.n;
UPDATE topics SET votes = votes + 96, long_n = long_n + 2, short_n = short_n + 1 WHERE code = 'DB0006';
